#!/usr/bin/env python3
"""Generates docs/evidence/p37/RESULTS.md from results/v2/h4-main/result.json. `--check` fails if the committed file differs."""
import json, os, sys
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..")
def build():
    r = json.load(open(os.path.join(ROOT, "results", "v2", "h4-main", "result.json"))); a = r["aggregate"]; B = [b for b in a["baselines"] if "-" not in b]
    L = ["# P37 results — HMIB / HCCB / HECB / HIEB × B0–B7 (CANDIDATE)", "", "_Generated by `bench/h4/report.py` from `results/v2/h4-main/result.json`; do not edit by hand. Synthetic fixtures, scripted toy models, one VM, no live model (L3), no pilot (L5)._", "",
         "## Headline (read the caveats under it before quoting)", "", "| Baseline | Layers | Attack types with forbidden effect | 95% Wilson CI | Attacks denied | Benign controls completed | False blocks | Control p50 s |", "|---|---|---|---|---|---|---|---|"]
    for b in B:
        x = a["baselines"][b]; L.append(f"| {b} | {', '.join(x['layers']) or 'none'} | {x['effects']}/{x['attack_scenarios']} | {x['effect_ci95_wilson'][0]:.3f}–{x['effect_ci95_wilson'][1]:.3f} | {x['attack_denied']} | {x['control_completed']}/{x['control_n']} | {x['false_blocks']} | {x['control_seconds_p50']} |")
    L += ["", "**Caveats that bound this table.** The 63 attack types and the layers were designed by the same author around the same threat classes, so a high B7 reduction measures *coverage of what was designed for*, not general security. B1 and B2 show no benefit because these suites do not exercise what a name-guard or an OS sandbox protects (the P29 benchmark did). B3 is a three-pattern emulation of generic scanners, not a real scanner (the real-tool comparison is P36's checkov run). One scenario type (HCCB-06, debug mode left on) is **still exposed under B7**: no layer covers it.", "",
          "## Paired against B0 (same 63 scenario types)", "", "| Baseline | B0-only effect | baseline-only effect | risk reduction | family-cluster bootstrap 95% CI | McNemar exact p | Holm p |", "|---|---|---|---|---|---|---|"]
    for b in B[1:]:
        p = a["paired_vs_B0"][b]; L.append(f"| {b} | {p['b0_only_effect']} | {p['baseline_only_effect']} | {p['risk_reduction']:.3f} | {p['family_cluster_bootstrap_ci95'][0]:.3f}–{p['family_cluster_bootstrap_ci95'][1]:.3f} | {p['mcnemar_exact_p']} | {p['holm_adjusted_p']} |")
    L += ["", "## By suite (effects / attack types)", "", "| Suite | " + " | ".join(B) + " |", "|---|" + "---|" * len(B)]
    for s, v in a["by_suite"].items(): L.append(f"| {s} | " + " | ".join(f"{v[b]['effects']}/{v[b]['attacks']}" for b in B) + " |")
    L += ["", "## By anti-leakage split (family-level; see splits note)", "", "| Split | " + " | ".join(B) + " |", "|---|" + "---|" * len(B)]
    for s, v in a["by_split"].items(): L.append(f"| {s} | " + " | ".join(f"{v[b]['effects']}/{v[b]['attacks']}" for b in B) + " |")
    L += ["", f"Splits: {r['splits']['leakage']['scenarios_per_split']} scenarios per split; straddling families: {len(r['splits']['leakage']['straddling_families'])}. The author wrote scenarios and guards together, so splits provide bookkeeping separation, not blind validation; nothing was tuned after assignment.", "",
          "## Leave-one-layer-out ablation of B7", "", f"B7 leaves {a['ablation']['B7_effects']}/{a['ablation']['attacks']} attack types exposed.", "", "| Layer removed | Effects | Marginal | Newly exposed |", "|---|---|---|---|"]
    for l, v in a["ablation"]["layers"].items(): L.append(f"| {l} | {v['effects_without_layer']} | {v['marginal_effects_attributable']} | {', '.join(v['scenarios_exposed']) or '—'} |")
    L += ["", "Layers with marginal 0 (`sandbox`, `scanners`, `toolguard`) add nothing *on this benchmark*; that is a statement about these suites, not about those layers.", "", "## Documented coverage limits per baseline", ""]
    for b in B: L.append(f"* **{b}** — {a['baselines'][b]['description']}. Limit: {a['baselines'][b]['coverage_limit']}.")
    L += ["", f"Outcome stability across repeats: {r['stability']['checked']} (scenario, baseline) outcomes checked, {len(r['stability']['unstable'])} unstable. Harness error rows: {sum(x['harness_error_rows'] for x in a['baselines'].values())}.", ""]
    return "\n".join(L)
if __name__ == "__main__":
    path = os.path.join(ROOT, "docs", "evidence", "p37", "RESULTS.md"); t = build()
    if "--check" in sys.argv:
        ok = os.path.exists(path) and open(path).read() == t; print("p37 RESULTS.md:", "MATCH" if ok else "MISMATCH"); sys.exit(0 if ok else 1)
    open(path, "w").write(t); print("wrote", path)
